import json
with open('/app/resources/treasury_bulletin_2003_03.json', 'r') as f:
    data = json.load(f)

# Search for CPI in the document
def find_in_element(elem, path=''):
    results = []
    if isinstance(elem, dict):
        if 'content' in elem and isinstance(elem['content'], str):
            if 'CPI' in elem['content'].upper() or 'consumer' in elem['content'].lower():
                results.append((path, elem['content'][:200]))
        for k, v in elem.items():
            results.extend(find_in_element(v, f'{path}.{k}'))
    elif isinstance(elem, list):
        for i, item in enumerate(elem):
            results.extend(find_in_element(item, f'{path}[{i}]'))
    elif isinstance(elem, str):
        if 'CPI' in elem.upper():
            results.append((path, elem[:200]))
    return results

results = find_in_element(data)
for r in results:
    print(f'{r[0]}: {r[1]}')
"
